// 店员来源由真实服务/原LE付款派生；NPC续行只履行已接受且有明确商品的原合同。
#include "private_shop_staff.hpp"
#include "private_shop_operation.hpp"
namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const StableId& code){return {false,{},common_failure(code).error};}
Status validate(const PrivateShopContext& x){if(!x.estates||!x.estate_access)return common_failure("PrivateShopLaborSourceUnavailable");return validate_private_shop_staff({x,x.catalog.staff,x.state.staff,*x.estates,x.estate_employment,x.estate_access});}
}
Outcome<std::vector<StableId>> PrivateShopStaffAccess::private_shop_worker_contracts(const StableId& actor)const{auto checked=validate(context_);if(!checked.ok)return {false,{},checked.error};if(!context_.common.actor(actor))return fail<std::vector<StableId>>("UnknownActor");std::vector<StableId> ids;for(const auto& row:context_.state.staff.contracts.rows())if(row.second.terms.worker_actor_id==actor)ids.push_back(row.first);return {true,std::move(ids),{}};}
Outcome<std::optional<PrivateShopStaffSource>> PrivateShopStaffAccess::private_shop_staff_source(const StableId& id)const{auto checked=validate(context_);if(!checked.ok)return {false,{},checked.error};const auto* contract=context_.state.staff.contracts.find(id);if(!contract)return {true,{}, {}};PrivateShopStaffSource out;out.source_identity=context_.common.state().identity;out.terms=contract->terms;out.contract_id=contract->id;out.status=contract->status;out.acceptance_fact_id=contract->id;out.terminal_fact_id=contract->terminal_fact_id;out.obligation_id=contract->obligation_id;out.accepted_tick=contract->accepted_tick;out.through_tick=contract->through_tick;for(const auto& row:context_.state.staff.services.rows())if(row.second.contract_id==id){if(!row.second.closing_fraction&&__builtin_add_overflow(out.served_ticks,Integer{1},&out.served_ticks))return fail<std::optional<PrivateShopStaffSource>>("PrivateShopStaffTotalOverflow");if(__builtin_add_overflow(out.earned_cash,row.second.amount,&out.earned_cash))return fail<std::optional<PrivateShopStaffSource>>("PrivateShopStaffTotalOverflow");}for(const auto& row:context_.economy.payments.rows())if(row.second.obligation_id==contract->obligation_id&&__builtin_add_overflow(out.paid_cash,row.second.amount,&out.paid_cash))return fail<std::optional<PrivateShopStaffSource>>("PrivateShopStaffTotalOverflow");const auto* wallet=context_.common.wallet(contract->terms.payer_wallet_id);if(!wallet)return fail<std::optional<PrivateShopStaffSource>>("PrivateShopStaffWalletMissing");for(const auto& hold:wallet->reserved){const auto* operation=context_.state.operations.find(hold.action_id.id);if(hold.action_id.kind==ReservationRef::Kind::action&&operation&&operation->staff_contract_id==id&&__builtin_add_overflow(out.reserved_cash,hold.amount,&out.reserved_cash))return fail<std::optional<PrivateShopStaffSource>>("PrivateShopStaffTotalOverflow");}return {true,std::move(out),{}};}
Status start_private_shop_npc_staff_work_in_candidate(CommonStore& common,LocalEconomyState& economy,PrivateShopState& state,const PrivateShopContext& x){if(&common!=&x.common||&economy!=&x.economy||&state!=&x.state||x.phase)return common_failure("PrivateShopStaffWorkCandidateMismatch");if(state.staff.contracts.empty())return common_success();auto checked=validate(x);if(!checked.ok)return checked;const auto contracts=state.staff.contracts.order();for(const auto& id:contracts){const auto contract=*state.staff.contracts.find(id);if(contract.status!="active"||contract.terms.worker_actor_id==common.state().metadata.player_actor_id)continue;const auto* shop=state.shops.find(contract.terms.shop_id);if(!shop||shop->status=="closed")continue;auto stock=common.count(shop->inventory_id,contract.terms.service_item_id,{{Owner::Kind::actor,contract.terms.employer_actor_id,{}}},{});if(!stock.ok)return {false,{},stock.error};if(stock.value==0)continue;auto quote=preview_private_shop_operation(x,contract.terms.worker_actor_id,{shop->id,contract.terms.service_item_id});if(!quote.ok){const auto& code=quote.error.original.code;if(quote.error.kind==ErrorKind::rule&&(code=="PrivateShopAttendanceUnavailable"||code=="PrivateShopStaffInjured"||code=="PrivateShopPresenceRequired"||code=="PrivateShopWorkerInArmy"||code=="PrivateShopWorkerAlreadyEmployed"||code=="PrivateShopWorkerEstateDuty"||code=="PrivateShopDailyFundsRequired"||code=="PrivateShopRentResumeRequired"||code=="PrivateShopDayAlreadyCommitted"||code=="PrivateShopStaffTermTooShort"))continue;return {false,{},quote.error};}auto started=start_private_shop_operation_in_candidate(common,economy,state,x,quote.value);if(!started.ok)return {false,{},started.error};}return common_success();}
}
